/* ============================================
   GlobalStone Design System
   Corporate Real Estate Services
   ============================================ */

/* --- OKLCH Color Tokens --- */
:root {
  /* Primary palette */
  --navy-primary: oklch(15% 0.04 250);
  --navy-primary-hex: #0A1628;
  --forest-green: oklch(28% 0.08 165);
  --forest-green-hex: #003F2D;
  --dark-teal: oklch(22% 0.06 195);
  --dark-teal-hex: #012A2D;

  /* Accent palette */
  --teal-accent: oklch(52% 0.1 195);
  --teal-accent-hex: #0A7E8C;
  --teal-light: oklch(62% 0.1 195);
  --teal-light-hex: #2BA5B5;
  --gold-accent: oklch(72% 0.14 80);
  --gold-accent-hex: #C5993A;

  /* Neutrals */
  --white: oklch(100% 0 0);
  --white-hex: #FFFFFF;
  --gray-50: oklch(97% 0.005 250);
  --gray-50-hex: #F7F8FA;
  --gray-100: oklch(94% 0.008 250);
  --gray-100-hex: #EDEEF2;
  --gray-200: oklch(90% 0.01 250);
  --gray-200-hex: #E6E6E6;
  --gray-300: oklch(82% 0.01 250);
  --gray-300-hex: #C8CAD0;
  --gray-400: oklch(68% 0.015 250);
  --gray-400-hex: #8E919A;
  --gray-500: oklch(55% 0.015 250);
  --gray-500-hex: #6B6E78;
  --gray-600: oklch(40% 0.02 250);
  --gray-600-hex: #454750;
  --gray-700: oklch(30% 0.02 250);
  --gray-700-hex: #2C2D33;
  --gray-800: oklch(22% 0.03 250);
  --gray-800-hex: #1A1B22;
  --gray-900: oklch(15% 0.04 250);
  --gray-900-hex: #0A0D17;

  /* Spacing Scale (8px base) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;
  --space-9: 128px;

  /* Typography */
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-heading: 'Playfair Display', Georgia, 'Times New Roman', serif;

  /* Sizing */
  --max-width: 1200px;
  --nav-height: 72px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(10, 22, 40, 0.08);
  --shadow-md: 0 4px 12px rgba(10, 22, 40, 0.1);
  --shadow-lg: 0 8px 32px rgba(10, 22, 40, 0.12);
  --shadow-xl: 0 16px 48px rgba(10, 22, 40, 0.16);

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
}

/* --- Reset & Base --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  color: var(--gray-800-hex);
  background: var(--white-hex);
  line-height: 1.6;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  text-decoration: none;
  color: inherit;
  transition: color var(--transition-fast);
}

ul, ol {
  list-style: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
  font-size: inherit;
}

input {
  font-family: inherit;
  font-size: inherit;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--navy-primary-hex);
}

h1 { font-size: clamp(2rem, 4vw, 3.25rem); }
h2 { font-size: clamp(1.75rem, 3vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2vw, 1.625rem); }
h4 { font-size: 1.125rem; }

p {
  margin-bottom: var(--space-3);
  line-height: 1.7;
}

.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-muted { color: var(--gray-500-hex); }

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-3);
}

@media (min-width: 640px) {
  .container { padding: 0 var(--space-4); }
}

@media (min-width: 1024px) {
  .container { padding: 0 var(--space-5); }
}

.section {
  padding: var(--space-7) 0;
}

@media (min-width: 1024px) {
  .section { padding: var(--space-8) 0; }
}

.section--dark {
  background: var(--navy-primary-hex);
  color: var(--white-hex);
}

.section--dark h2,
.section--dark h3,
.section--dark h4 {
  color: var(--white-hex);
}

.section--gray {
  background: var(--gray-50-hex);
}

.section--teal {
  background: var(--forest-green-hex);
  color: var(--white-hex);
}

.section--teal h2,
.section--teal h3 {
  color: var(--white-hex);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 28px;
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-sm);
  transition: all var(--transition-base);
  letter-spacing: 0.01em;
  gap: var(--space-2);
  text-align: center;
}

.btn--primary {
  background: var(--teal-accent-hex);
  color: var(--white-hex);
}

.btn--primary:hover {
  background: var(--teal-light-hex);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn--secondary {
  background: transparent;
  color: var(--white-hex);
  border: 2px solid var(--white-hex);
}

.btn--secondary:hover {
  background: var(--white-hex);
  color: var(--navy-primary-hex);
}

.btn--outline {
  background: transparent;
  color: var(--teal-accent-hex);
  border: 2px solid var(--teal-accent-hex);
}

.btn--outline:hover {
  background: var(--teal-accent-hex);
  color: var(--white-hex);
}

.btn--gold {
  background: var(--gold-accent-hex);
  color: var(--navy-primary-hex);
}

.btn--gold:hover {
  filter: brightness(1.1);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn--dark {
  background: var(--navy-primary-hex);
  color: var(--white-hex);
}

.btn--dark:hover {
  background: var(--forest-green-hex);
}

.btn--link {
  padding: 0;
  color: var(--teal-accent-hex);
  font-weight: 600;
  gap: var(--space-1);
}

.btn--link:hover {
  color: var(--teal-light-hex);
}

.btn--link::after {
  content: '\2192';
  transition: transform var(--transition-fast);
}

.btn--link:hover::after {
  transform: translateX(4px);
}

.btn--link-white {
  color: var(--white-hex);
}

.btn--link-white:hover {
  color: var(--gray-200-hex);
}

/* --- Header & Navigation --- */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--navy-primary-hex);
  height: var(--nav-height);
  transition: background var(--transition-base), box-shadow var(--transition-base);
}

.header.scrolled {
  background: rgba(10, 22, 40, 0.97);
  box-shadow: var(--shadow-lg);
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-3);
}

@media (min-width: 1024px) {
  .header__inner { padding: 0 var(--space-5); }
}

.header__logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--white-hex);
  letter-spacing: -0.02em;
  flex-shrink: 0;
}

.header__logo span {
  color: var(--gold-accent-hex);
}

/* Desktop Nav */
.nav-desktop {
  display: none;
  align-items: center;
  height: 100%;
}

@media (min-width: 1024px) {
  .nav-desktop { display: flex; }
}

.nav-desktop__list {
  display: flex;
  align-items: center;
  height: 100%;
  gap: 0;
}

.nav-desktop__item {
  position: relative;
  height: 100%;
  display: flex;
  align-items: center;
}

.nav-desktop__link {
  display: flex;
  align-items: center;
  height: 100%;
  padding: 0 var(--space-3);
  color: var(--gray-300-hex);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color var(--transition-fast);
  white-space: nowrap;
  gap: var(--space-1);
}

.nav-desktop__link:hover,
.nav-desktop__link.active {
  color: var(--white-hex);
}

.nav-desktop__link .arrow {
  font-size: 0.625rem;
  transition: transform var(--transition-fast);
}

.nav-desktop__item:hover .arrow,
.nav-desktop__item.open .arrow {
  transform: rotate(180deg);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  width: 680px;
  background: var(--white-hex);
  box-shadow: var(--shadow-xl);
  border-radius: 0 0 var(--radius-lg) var(--radius-lg);
  padding: var(--space-5);
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--transition-base), visibility var(--transition-base);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-5);
}

.nav-desktop__item:hover .mega-menu,
.nav-desktop__item.open .mega-menu {
  opacity: 1;
  visibility: visible;
}

.mega-menu__col h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gray-400-hex);
  margin-bottom: var(--space-3);
  padding-bottom: var(--space-2);
  border-bottom: 1px solid var(--gray-200-hex);
}

.mega-menu__link {
  display: block;
  padding: var(--space-2) 0;
  color: var(--gray-700-hex);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: color var(--transition-fast), padding-left var(--transition-fast);
}

.mega-menu__link:hover {
  color: var(--teal-accent-hex);
  padding-left: var(--space-2);
}

/* Mobile Nav */
.nav-mobile-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  color: var(--white-hex);
}

@media (min-width: 1024px) {
  .nav-mobile-toggle { display: none; }
}

.hamburger {
  width: 24px;
  height: 16px;
  position: relative;
}

.hamburger span {
  display: block;
  position: absolute;
  width: 100%;
  height: 2px;
  background: var(--white-hex);
  border-radius: 2px;
  transition: all var(--transition-base);
}

.hamburger span:nth-child(1) { top: 0; }
.hamburger span:nth-child(2) { top: 7px; }
.hamburger span:nth-child(3) { bottom: 0; }

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg);
  top: 7px;
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg);
  bottom: 7px;
}

.nav-mobile {
  display: none;
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--navy-primary-hex);
  overflow-y: auto;
  z-index: 999;
  padding: var(--space-3);
}

.nav-mobile.active {
  display: block;
}

.nav-mobile__item {
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.nav-mobile__link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-3) var(--space-2);
  color: var(--white-hex);
  font-size: 1.0625rem;
  font-weight: 500;
}

.nav-mobile__link .arrow {
  font-size: 0.75rem;
  transition: transform var(--transition-fast);
}

.nav-mobile__link.open .arrow {
  transform: rotate(180deg);
}

.nav-mobile__submenu {
  display: none;
  padding: 0 var(--space-2) var(--space-3);
}

.nav-mobile__submenu.active {
  display: block;
}

.nav-mobile__submenu h5 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gold-accent-hex);
  margin: var(--space-2) 0;
}

.nav-mobile__submenu a {
  display: block;
  padding: var(--space-2) 0;
  color: var(--gray-300-hex);
  font-size: 0.9375rem;
}

.nav-mobile__submenu a:hover {
  color: var(--white-hex);
}

/* --- Hero --- */
.hero {
  position: relative;
  min-height: 520px;
  display: flex;
  align-items: flex-end;
  padding: calc(var(--nav-height) + var(--space-5)) 0 var(--space-7);
  overflow: hidden;
}

@media (min-width: 1024px) {
  .hero { min-height: 600px; }
}

.hero__bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero__bg-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(10, 22, 40, 0.85) 0%,
    rgba(0, 63, 45, 0.7) 50%,
    rgba(1, 42, 45, 0.6) 100%
  );
}

.hero__content {
  position: relative;
  z-index: 1;
  max-width: 680px;
}

.hero__tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gold-accent-hex);
  margin-bottom: var(--space-3);
}

.hero h1 {
  color: var(--white-hex);
  margin-bottom: var(--space-3);
  line-height: 1.15;
}

.hero p {
  color: var(--gray-300-hex);
  font-size: 1.125rem;
  margin-bottom: var(--space-5);
  max-width: 540px;
}

/* Sub-page hero (smaller) */
.hero--sub {
  min-height: 360px;
  padding-top: calc(var(--nav-height) + var(--space-6));
}

@media (min-width: 1024px) {
  .hero--sub { min-height: 400px; }
}

.hero--sub h1 {
  font-size: clamp(1.75rem, 3.5vw, 2.75rem);
}

/* --- Cards --- */
.card {
  background: var(--white-hex);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.card__image {
  width: 100%;
  aspect-ratio: 16/10;
  background: var(--gray-200-hex);
  overflow: hidden;
}

.card__image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.card:hover .card__image img {
  transform: scale(1.05);
}

.card__body {
  padding: var(--space-4);
}

.card__tag {
  display: inline-block;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--teal-accent-hex);
  margin-bottom: var(--space-2);
}

.card__title {
  font-size: 1.0625rem;
  margin-bottom: var(--space-2);
  color: var(--navy-primary-hex);
  line-height: 1.4;
}

.card__meta {
  font-size: 0.8125rem;
  color: var(--gray-500-hex);
}

/* Insight card */
.insight-card {
  display: flex;
  flex-direction: column;
  background: var(--white-hex);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
  border: 1px solid var(--gray-100-hex);
}

.insight-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.insight-card__image {
  width: 100%;
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, var(--navy-primary-hex), var(--dark-teal-hex));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400-hex);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  position: relative;
  overflow: hidden;
}

.insight-card__image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(10,22,40,0.6), rgba(0,63,45,0.3));
}

.insight-card__body {
  padding: var(--space-4);
  flex: 1;
  display: flex;
  flex-direction: column;
}

.insight-card__tag {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--teal-accent-hex);
  margin-bottom: var(--space-2);
}

.insight-card__title {
  font-family: var(--font-heading);
  font-size: 1.0625rem;
  line-height: 1.4;
  margin-bottom: var(--space-2);
  color: var(--navy-primary-hex);
}

.insight-card__date {
  margin-top: auto;
  font-size: 0.8125rem;
  color: var(--gray-500-hex);
}

/* Service card */
.service-card {
  background: var(--white-hex);
  border: 1px solid var(--gray-100-hex);
  border-radius: var(--radius-md);
  padding: var(--space-5);
  transition: all var(--transition-base);
}

.service-card:hover {
  border-color: var(--teal-accent-hex);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.service-card__icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, var(--forest-green-hex), var(--dark-teal-hex));
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-3);
  color: var(--white-hex);
  font-size: 1.25rem;
}

.service-card h3 {
  font-size: 1.25rem;
  margin-bottom: var(--space-2);
}

.service-card p {
  color: var(--gray-500-hex);
  font-size: 0.9375rem;
  margin-bottom: var(--space-3);
}

/* Capability card */
.capability-card {
  background: var(--white-hex);
  border: 1px solid var(--gray-100-hex);
  border-radius: var(--radius-md);
  padding: var(--space-5);
  transition: all var(--transition-base);
}

.capability-card:hover {
  border-color: var(--teal-accent-hex);
  box-shadow: var(--shadow-md);
}

.capability-card__icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--gray-50-hex);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-3);
  color: var(--teal-accent-hex);
  font-size: 1.125rem;
}

.capability-card h4 {
  margin-bottom: var(--space-2);
  color: var(--navy-primary-hex);
}

.capability-card p {
  color: var(--gray-500-hex);
  font-size: 0.9375rem;
  margin-bottom: var(--space-3);
}

/* --- Announcement Banner --- */
.announcement {
  background: linear-gradient(135deg, var(--forest-green-hex), var(--dark-teal-hex));
  padding: var(--space-4) 0;
}

.announcement__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  flex-wrap: wrap;
}

.announcement__text {
  font-size: 0.9375rem;
  color: var(--white-hex);
  font-weight: 500;
}

.announcement__cta {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gold-accent-hex);
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  transition: gap var(--transition-fast);
}

.announcement__cta:hover {
  gap: var(--space-2);
  color: var(--white-hex);
}

/* --- About Statement --- */
.about-statement {
  padding: var(--space-8) 0;
}

.about-statement__inner {
  display: grid;
  gap: var(--space-5);
  align-items: center;
}

@media (min-width: 1024px) {
  .about-statement__inner {
    grid-template-columns: 1fr 1fr;
    gap: var(--space-7);
  }
}

.about-statement__content h2 {
  margin-bottom: var(--space-4);
}

.about-statement__content p {
  font-size: 1.0625rem;
  color: var(--gray-500-hex);
  line-height: 1.8;
}

.about-statement__image {
  width: 100%;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--gray-100-hex), var(--gray-200-hex));
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gray-400-hex);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  position: relative;
  overflow: hidden;
}

.about-statement__image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(10,22,40,0.15), rgba(0,63,45,0.1));
}

/* --- What We Do Tabs --- */
.what-we-do {
  padding: var(--space-8) 0;
